// PROGRAMMATIC: TransactionTemplate — per-batch TX with independent commits
package com.bank.interest.service;

import com.bank.interest.model.SavingsAccount;
import com.bank.interest.repository.SavingsAccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import java.math.BigDecimal;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class ProgrammaticInterestService {

    private final SavingsAccountRepository accountRepo;
    private final TransactionTemplate txTemplate;

    @Value("${batch.chunk-size:500}")
    private int chunkSize;

    /**
     * PROGRAMMATIC: TransactionTemplate — each batch is a SEPARATE transaction.
     * If batch 3 fails, batches 1-2 are already COMMITTED (partial progress saved).
     *
     * Benefits over @Transactional:
     * 1. Multiple independent TXs in one method (batch commits)
     * 2. No self-invocation proxy problem (no proxy needed — YOU control TX)
     * 3. Mix TX and non-TX code in same method
     * 4. Dynamic TX boundaries (decide at runtime whether to use TX)
     */
    public int calculateInterestProgrammatic() {
        // This line runs WITHOUT a transaction (no @Transactional, no template)
        List<SavingsAccount> accounts = accountRepo.findByStatus("ACTIVE");
        log.info("[PROGRAMMATIC] Processing {} accounts in batches of {}", accounts.size(), chunkSize);

        int totalProcessed = 0;
        int batchNumber = 0;

        for (int i = 0; i < accounts.size(); i += chunkSize) {
            batchNumber++;
            List<SavingsAccount> batch = accounts.subList(i, Math.min(i + chunkSize, accounts.size()));
            int batchNum = batchNumber;  // effectively final for lambda

            // Each batch is its OWN transaction — commits independently
            Integer batchProcessed = txTemplate.execute(status -> {
                int processed = 0;
                for (SavingsAccount account : batch) {
                    try {
                        BigDecimal interest = account.calculateMonthlyInterest();
                        account.creditInterest(interest);
                        accountRepo.save(account);
                        processed++;
                        log.info("  Batch {}: {} → Rs.{} interest", batchNum,
                            account.getAccountId(), interest);
                    } catch (Exception e) {
                        // Option A: skip this account, continue batch
                        log.warn("  Batch {}: {} FAILED: {}", batchNum,
                            account.getAccountId(), e.getMessage());
                        // Option B: rollback entire batch
                        // status.setRollbackOnly();
                        // return processed;
                    }
                }
                return processed;
            });
            // COMMIT happens here (end of txTemplate.execute)

            totalProcessed += (batchProcessed != null ? batchProcessed : 0);
            log.info("[PROGRAMMATIC] Batch {} committed: {} accounts (total: {})",
                batchNumber, batchProcessed, totalProcessed);
        }

        return totalProcessed;
    }

    /**
     * executeWithoutResult: for void operations
     * status.setRollbackOnly(): manual rollback trigger
     */
    public void manualRollbackExample(String accountId) {
        txTemplate.executeWithoutResult(status -> {
            SavingsAccount account = accountRepo.findById(accountId).orElseThrow();
            BigDecimal interest = account.calculateMonthlyInterest();
            account.creditInterest(interest);
            accountRepo.save(account);

            // Decide at runtime whether to rollback
            if (interest.compareTo(new BigDecimal("10000")) > 0) {
                log.warn("Interest Rs.{} exceeds limit — rolling back!", interest);
                status.setRollbackOnly();  // MANUAL rollback — nothing saved
            }
        });
    }
}
