package com.bank.interest.controller;

import com.bank.interest.service.*;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/interest")
@RequiredArgsConstructor
public class InterestController {

    private final DeclarativeInterestService declarativeService;
    private final ProgrammaticInterestService programmaticService;

    // Declarative: single TX — all or nothing
    @PostMapping("/calculate/declarative")
    public String calculateDeclarative() {
        int count = declarativeService.calculateInterestDeclarative();
        return "Declarative: processed " + count + " accounts in 1 transaction";
    }

    // Programmatic: per-batch TX — partial progress saved
    @PostMapping("/calculate/programmatic")
    public String calculateProgrammatic() {
        int count = programmaticService.calculateInterestProgrammatic();
        return "Programmatic: processed " + count + " accounts in multiple transactions";
    }
}
