@ExtendWith(MockitoExtension.class)
class ProgrammaticInterestServiceTest {

    @Mock SavingsAccountRepository accountRepo;
    @Mock TransactionTemplate txTemplate;
    @InjectMocks ProgrammaticInterestService service;

    @Test
    void shouldProcessInBatches() {
        SavingsAccount acc = mock(SavingsAccount.class);
        when(acc.calculateMonthlyInterest()).thenReturn(new java.math.BigDecimal("333.33"));
        when(acc.getAccountId()).thenReturn("SAV001");
        when(accountRepo.findByStatus("ACTIVE")).thenReturn(List.of(acc));
        when(txTemplate.execute(any())).thenReturn(1);

        int count = service.calculateInterestProgrammatic();

        assertThat(count).isEqualTo(1);
        verify(txTemplate).execute(any());  // TransactionTemplate was used, not @Transactional
    }
}
